const campo = document.querySelector('#email');
campo.setCustomValidity('E-mail inválido');
console.log(campo.checkValidity() + ' ' + campo.validationMessage);

const form = document.querySelector('#f');
form.addEventListener('submit', (evento) => {
  evento.preventDefault();
});
const resultado = form.dispatchEvent(new Event('submit', { cancelable: true }));
console.log(resultado);

const form = document.querySelector('#f');
const campo = document.querySelector('#nome');
campo.value = 'Ana';
form.reset();
console.log(campo.value);

const form = document.querySelector('#f');
const dados = new FormData(form);
fetch('http://localhost:3000/alunos', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ nome: dados.get('nome') }),
})
  .then((resposta) => resposta.json())
  .then((aluno) => console.log(aluno.id));
